import type { NotionContrastMode } from "@notionhq/custom-blocks-protocol/contrast.js"
import type { NotionDataSource } from "@notionhq/custom-blocks-protocol/dataSources/dataSource.js"
import type { NotionBlockId } from "@notionhq/custom-blocks-protocol/ids.js"
import { CustomBlockInitializationError } from "@notionhq/custom-blocks-protocol/messages/init.js"
import type { CustomBlockPage } from "@notionhq/custom-blocks-protocol/pages/page.js"
import type { NotionParent } from "@notionhq/custom-blocks-protocol/parent.js"
import type { NotionTheme } from "@notionhq/custom-blocks-protocol/theme.js"
import type { NotionUser } from "@notionhq/custom-blocks-protocol/users/user.js"
import { attemptToLoadSelfHostedManifest } from "./bridge/loadManifest.js"
import { customBlockHost } from "./bridge/sandboxClient.js"
import { unreachable } from "./utils.js"

/**
 * The payload sent by the host in the `init` message in response to the sandbox's `connect` message.
 */
export type CustomBlockInitPayload = {
	theme: NotionTheme
	contrastMode: NotionContrastMode
	blockId: NotionBlockId
	parent: NotionParent
	page: CustomBlockPage
	currentUser: NotionUser
	dataSources: NotionDataSource[]
}

/**
 * Error thrown when the SDK is loaded in a top-level standalone window with no parent frame.
 * `postMessage` would just hit the same window and the handshake can never complete.
 * `<NotionCustomBlock>` catches this specifically and falls back to a standalone preview with a
 * warning banner. Direct callers can `instanceof` it to apply their own policy.
 */
export class NotInIframeError extends CustomBlockInitializationError {
	constructor(message: string = NOT_IN_IFRAME_MESSAGE) {
		super({
			code: "not_in_iframe",
			message,
			isRetryable: false,
		})
		this.name = "NotInIframeError"
	}

	declare code: "not_in_iframe"
}

const NOT_IN_IFRAME_MESSAGE =
	"<NotionCustomBlock> only works inside an iframe — use the dev shell or deploy to Notion."

let initPromise: Promise<CustomBlockInitPayload> | undefined

/**
 * Initializes the custom block by running the SDK <-> host handshake.
 *
 * Resolves with the block's initial context (theme, block location, current
 * user, data sources) once the host has initialized the block. Rejects with a
 * `CustomBlockInitializationError` if initialization fails.
 *
 * Idempotent: subsequent calls return the same promise as the first.
 * Mount your React tree (or call any SDK hook) only after the returned promise resolves.
 */
export function initCustomBlock(): Promise<CustomBlockInitPayload> {
	if (initPromise === undefined) {
		customBlockHost.start()
		initPromise = performHandshake()
	}
	return initPromise
}

/**
 * Performs the host <-> sandbox SDK handshake:
 * 1. On localhost, attempts to load the worker manifest from the page-relative
 *    `manifest` path
 * 2. Sends `connect` with the manifest
 * 3. Awaits the host's `init` message
 * 4. Applies the `init` payload and acknowledges with `initResult` (fire-and-forget)
 *
 * Resolves with the `init` payload after the process above. Rejects with a
 * `CustomBlockInitializationError` if any step fails.
 */
async function performHandshake(): Promise<CustomBlockInitPayload> {
	try {
		// Fail fast with a typed error when rendered as a standalone tab and not in a parent frame.
		// Otherwise, `postMessage` to `window.parent` would just hit the same window and never
		// arrive.
		if (typeof window !== "undefined" && window.parent === window) {
			throw new NotInIframeError()
		}

		// Load the manifest and send it to the host.
		const manifestResult = await attemptToLoadSelfHostedManifest()
		customBlockHost.sendConnect(manifestResult)

		await customBlockHost.awaitInit()

		const hostState = customBlockHost.getState()
		switch (hostState.status) {
			case "initialized":
				return {
					theme: hostState.theme,
					contrastMode: hostState.contrastMode,
					blockId: hostState.blockId,
					parent: hostState.parent,
					page: hostState.page,
					currentUser: hostState.currentUser,
					dataSources: hostState.dataSources,
				}
			case "uninitialized":
				throw new CustomBlockInitializationError({
					code: "context_unavailable",
					message: "Host block payload is unavailable.",
					isRetryable: true,
				})
			default:
				return unreachable(hostState)
		}
	} catch (error) {
		if (error instanceof CustomBlockInitializationError) {
			throw error
		}
		const message = error instanceof Error ? error.message : String(error)
		throw new CustomBlockInitializationError({
			code: "unknown_error",
			message,
			isRetryable: false,
		})
	}
}
